import selfies as sf
from rdkit import Chem
parts=['[C][C][C][C][C][=N][O][C][Branch1][Ring1][C][O][=C][Ring1][#Branch1][C][O][C][=C][C][=C][Branch1][#Branch1][C][=Branch1][C][=O][O][C][C][=N][Ring1][#Branch2]','[C][C][O][C][C][O][Ring1][=Branch1]','[Na+1]','[OH1-1]']
for i,p in enumerate(parts):
    try:
        smi=sf.decoder(p)
        m=Chem.MolFromSmiles(smi)
        print(i, 'SELFIES:',p)
        print('SMILES:',smi)
        print('canonical:',Chem.MolToSmiles(m) if m else None)
        if m:
            print('formula:',Chem.rdMolDescriptors.CalcMolFormula(m),'MW:',Chem.Descriptors.MolWt(m))
    except Exception as e: print(i,'ERROR',repr(e))
